// A small FTP server, enough to download from.
//
// Written rather than installed because the alternative is asking anyone who
// runs this suite to set up an FTP daemon, and because a server under this
// much control can be made to behave badly on purpose — refusing REST is a
// real and common thing that the client has to survive.
//
// Serves the same generated byte sequence as the HTTP mock, so a file
// fetched over FTP can be checked against the identical expectation.
//
//   node ftp-server.mjs --port 2121 [--no-rest] [--no-size]

import { createServer } from "node:net";

function arg(name, fallback) {
  const index = process.argv.indexOf(`--${name}`);
  if (index === -1) return fallback;
  const value = Number(process.argv[index + 1]);
  return Number.isFinite(value) ? value : fallback;
}

const PORT = arg("port", 2121);
const SIZE = arg("size", 1024 * 1024);
// Plenty of real servers refuse one or both of these.
const ALLOW_REST = !process.argv.includes("--no-rest");
const ALLOW_SIZE = !process.argv.includes("--no-size");

/** The same sequence the HTTP mock serves, so results can be compared. */
function byteAt(offset) {
  let x = (offset + 0x9e3779b9) | 0;
  x = Math.imul(x ^ (x >>> 16), 0x85ebca6b);
  x = Math.imul(x ^ (x >>> 13), 0xc2b2ae35);
  x = x ^ (x >>> 16);
  return x & 0xff;
}

function bodyFor(start, end) {
  const buffer = Buffer.allocUnsafe(Math.max(0, end - start));
  for (let i = 0; i < buffer.length; i += 1) buffer[i] = byteAt(start + i);
  return buffer;
}

/** Size of the file a path names: /file-<n>.bin is n bytes. */
function sizeOf(path) {
  const match = /file-(\d+)\.bin$/.exec(path);
  return match ? Number(match[1]) : SIZE;
}

const server = createServer((control) => {
  control.setNoDelay(true);

  let restOffset = 0;
  let passive = null; // { server, socket }
  let loggedIn = false;

  const say = (line) => control.write(`${line}\r\n`);

  /** Opens a listening socket for the data connection and announces it. */
  function enterPassive() {
    if (passive?.server) passive.server.close();

    const data = createServer();
    passive = { server: data, socket: null, waiting: [] };

    data.on("connection", (socket) => {
      socket.setNoDelay(true);
      passive.socket = socket;
      for (const resolve of passive.waiting.splice(0)) resolve(socket);
    });

    data.listen(0, "127.0.0.1", () => {
      const { port } = data.address();
      // PASV reports the address as six comma-separated numbers.
      const high = Math.floor(port / 256);
      const low = port % 256;
      say(`227 Entering Passive Mode (127,0,0,1,${high},${low}).`);
    });
  }

  /** The data socket, once the client has connected to it. */
  function dataSocket() {
    if (passive?.socket) return Promise.resolve(passive.socket);
    return new Promise((resolve) => passive.waiting.push(resolve));
  }

  async function retrieve(path) {
    const total = sizeOf(path);
    const from = Math.min(restOffset, total);
    restOffset = 0;

    say("150 Opening BINARY mode data connection.");
    const socket = await dataSocket();

    // Written in pieces so a large file does not become one allocation, and
    // so an interrupted transfer looks like a real one.
    const CHUNK = 64 * 1024;
    for (let offset = from; offset < total; offset += CHUNK) {
      const end = Math.min(offset + CHUNK, total);
      if (!socket.write(bodyFor(offset, end))) {
        await new Promise((resolve) => socket.once("drain", resolve));
      }
    }
    socket.end();
    passive.server.close();
    passive = null;
    say("226 Transfer complete.");
  }

  say("220 Divine IDM test server");

  let buffered = "";
  control.on("data", async (chunk) => {
    buffered += chunk.toString("latin1");

    let newline;
    while ((newline = buffered.indexOf("\r\n")) !== -1) {
      const line = buffered.slice(0, newline);
      buffered = buffered.slice(newline + 2);

      const [rawVerb, ...rest] = line.split(" ");
      const verb = rawVerb.toUpperCase();
      const argument = rest.join(" ");

      switch (verb) {
        case "USER":
          say("331 Please send the password.");
          break;
        case "PASS":
          loggedIn = true;
          say("230 Logged in.");
          break;
        case "SYST":
          say("215 UNIX Type: L8");
          break;
        case "FEAT":
          control.write("211-Features:\r\n");
          if (ALLOW_REST) control.write(" REST STREAM\r\n");
          if (ALLOW_SIZE) control.write(" SIZE\r\n");
          say("211 End");
          break;
        case "TYPE":
          say("200 Type set.");
          break;
        case "PWD":
          say('257 "/" is the current directory');
          break;
        case "CWD":
          say("250 Directory changed.");
          break;
        case "SIZE":
          if (!ALLOW_SIZE) say("550 SIZE not understood.");
          else say(`213 ${sizeOf(argument)}`);
          break;
        case "REST":
          if (!ALLOW_REST) {
            say("502 REST not implemented.");
          } else {
            restOffset = Number(argument) || 0;
            say(`350 Restarting at ${restOffset}.`);
          }
          break;
        case "EPSV":
          // Answered with a refusal so the client falls back to PASV, which
          // is the path worth exercising.
          say("500 EPSV not understood.");
          break;
        case "PASV":
          if (!loggedIn) say("530 Not logged in.");
          else enterPassive();
          break;
        case "RETR":
          if (!loggedIn) say("530 Not logged in.");
          else await retrieve(argument);
          break;
        case "QUIT":
          say("221 Goodbye.");
          control.end();
          break;
        default:
          say(`500 ${verb} not understood.`);
      }
    }
  });

  control.on("error", () => {});
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`ftp-server listening on ftp://127.0.0.1:${PORT}`);
  console.log(`  REST ${ALLOW_REST ? "allowed" : "refused"}, SIZE ${ALLOW_SIZE ? "allowed" : "refused"}`);
});
